// Comprehensive cybersecurity interview question database
// Covers 12 categories across 4 difficulty levels

export const SECURITY_INTERVIEW_DB = [
  // ============================================================
  // NETWORK SECURITY
  // ============================================================
  { question: "Explain the TCP three-way handshake and how it can be exploited.", answer: "The TCP three-way handshake establishes a connection via SYN, SYN-ACK, and ACK packets. The client sends a SYN with an initial sequence number, the server responds with SYN-ACK (acknowledging and providing its own sequence number), and the client completes with ACK. This can be exploited through SYN flood attacks where an attacker sends many SYN packets without completing the handshake, exhausting the server's half-open connection table. TCP sequence prediction attacks attempt to guess ISNs to hijack connections. SYN cookies are a defense that encodes connection state in the sequence number, avoiding the need to store half-open connections.", category: "Network Security", difficulty: "Junior", followUps: ["What are SYN cookies and how do they mitigate SYN floods?", "How does TCP Fast Open differ?"], keywords: ["TCP", "handshake", "SYN flood", "sequence number"] },
  { question: "What is the difference between a stateful and stateless firewall?", answer: "A stateless firewall examines each packet individually against its rule set, checking source/destination IP, ports, and protocol without maintaining any knowledge of previous packets. A stateful firewall tracks the state of active connections and makes decisions based on the context of the traffic flow (e.g., it knows a packet is part of an established TCP session). Stateful firewalls can detect and block attacks that exploit the stateless approach, such as ACK scans or packets that don't belong to any known connection. However, stateful firewalls consume more resources to maintain their connection state tables and can be vulnerable to state table exhaustion attacks.", category: "Network Security", difficulty: "Junior", followUps: ["What is a next-generation firewall (NGFW)?", "How does deep packet inspection work?"], keywords: ["firewall", "stateful", "stateless", "packet filtering"] },
  { question: "How does ARP spoofing work and how can you detect it?", answer: "ARP spoofing exploits the stateless nature of ARP (Address Resolution Protocol) by sending forged ARP reply packets to associate the attacker's MAC address with the IP address of another host (typically the default gateway). Since ARP has no authentication mechanism, hosts accept these unsolicited replies and update their ARP cache. This positions the attacker as a man-in-the-middle, intercepting traffic between the victim and gateway. Detection methods include monitoring for duplicate ARP replies, watching for ARP cache changes, using tools like arpwatch or arpalert to track MAC-IP bindings, enabling Dynamic ARP Inspection (DAI) on managed switches, and implementing 802.1X port-based authentication.", category: "Network Security", difficulty: "Mid", followUps: ["What is Gratuitous ARP?", "How does DHCP snooping help prevent ARP attacks?"], keywords: ["ARP", "spoofing", "MITM", "layer 2"] },
  { question: "Explain how DNS tunneling works and how to detect it.", answer: "DNS tunneling encodes data within DNS queries and responses, using the DNS protocol as a covert communication channel to bypass firewalls and network restrictions. The attacker registers a domain and sets up an authoritative DNS server. The client encodes data in subdomain labels of DNS queries (e.g., encoded-data.evil.com), and the server responds with encoded data in TXT, CNAME, or other record types. Detection involves monitoring for unusually long DNS queries (subdomain labels > 50 characters), high volume of DNS requests to a single domain, unusual record types (TXT queries in bulk), high entropy in domain names, and DNS requests to recently registered or low-reputation domains. Tools like passivedns, dnstap, and Zeek can help with detection.", category: "Network Security", difficulty: "Senior", followUps: ["Name common DNS tunneling tools.", "How would you block DNS tunneling at the network level?"], keywords: ["DNS", "tunneling", "exfiltration", "covert channel"] },
  { question: "What is BGP hijacking and why is it a significant threat?", answer: "BGP hijacking occurs when an autonomous system (AS) announces IP prefixes it doesn't legitimately own, causing internet traffic to be routed through the attacker's network. Since BGP relies on trust between peers and has no built-in authentication for route announcements, any AS can announce any prefix. This enables traffic interception, man-in-the-middle attacks on a massive scale, traffic blackholing (denial of service), or cryptocurrency theft by redirecting mining pool connections. Notable incidents include Pakistan Telecom's accidental hijack of YouTube (2008) and multiple cryptocurrency-targeting BGP hijacks. Defenses include RPKI (Resource Public Key Infrastructure), ROV (Route Origin Validation), BGP monitoring services, and prefix filtering.", category: "Network Security", difficulty: "Principal", followUps: ["What is RPKI and how does it prevent BGP hijacking?", "Explain the difference between a BGP hijack and a BGP leak."], keywords: ["BGP", "routing", "AS", "hijacking"] },
  { question: "What is the difference between IDS and IPS, and when would you use each?", answer: "An Intrusion Detection System (IDS) monitors network traffic passively and generates alerts when it detects suspicious activity, but does not block traffic. An Intrusion Prevention System (IPS) sits inline in the traffic path and can actively block or drop malicious packets in real-time. IDS is used when you want visibility without risk of blocking legitimate traffic (monitoring mode), while IPS is used when you need active protection. IDS is typically deployed out-of-band using a SPAN/mirror port, while IPS must be inline. The tradeoff is that IPS can introduce latency and false positives can block legitimate traffic, while IDS only provides detection without prevention.", category: "Network Security", difficulty: "Junior", followUps: ["What are Snort and Suricata?", "Explain the difference between signature-based and anomaly-based detection."], keywords: ["IDS", "IPS", "detection", "prevention"] },
  { question: "How does a VLAN hopping attack work and what are the mitigations?", answer: "VLAN hopping allows an attacker to access traffic on other VLANs that should be isolated. Two main techniques exist: switch spoofing and double tagging. In switch spoofing, the attacker configures their port to act as a trunk port by negotiating DTP (Dynamic Trunking Protocol), gaining access to all VLANs. In double tagging, the attacker sends frames with two 802.1Q tags; the first switch strips the outer tag and forwards the frame to the target VLAN based on the inner tag. Mitigations include disabling DTP on all access ports (switchport mode access, switchport nonegotiate), setting the native VLAN to an unused VLAN, explicitly configuring trunk ports, and enabling VLAN access control lists (VACLs).", category: "Network Security", difficulty: "Mid", followUps: ["What is the native VLAN and why does it matter for security?", "How does 802.1X enhance VLAN security?"], keywords: ["VLAN", "hopping", "802.1Q", "DTP", "switch"] },
  { question: "Describe how TLS 1.3 improves upon TLS 1.2 from a security perspective.", answer: "TLS 1.3 made several significant security improvements: it removed support for vulnerable algorithms (RSA key exchange, CBC mode ciphers, SHA-1, RC4, DES, 3DES, static Diffie-Hellman), mandating perfect forward secrecy with ephemeral key exchange only (ECDHE/DHE). It reduced the handshake to a single round trip (1-RTT) and supports zero round trip resumption (0-RTT) for repeat connections, though 0-RTT is vulnerable to replay attacks. The handshake is encrypted after the ServerHello, hiding certificate information from passive observers. The cipher suite concept was simplified to only five options, all using AEAD (authenticated encryption with associated data). These changes eliminated entire classes of attacks including BEAST, Lucky13, POODLE, and most padding oracle attacks.", category: "Network Security", difficulty: "Senior", followUps: ["What are the security concerns with TLS 1.3 0-RTT?", "How does encrypted SNI (ESNI/ECH) work?"], keywords: ["TLS", "1.3", "forward secrecy", "AEAD", "handshake"] },
  { question: "What is network segmentation and how does it improve security?", answer: "Network segmentation divides a network into isolated segments with controlled communication between them, limiting an attacker's ability to move laterally after initial compromise. It follows the principle of least privilege at the network level. Implementation approaches include physical separation, VLANs, firewalls between segments, software-defined networking (SDN), and micro-segmentation. A common model places web servers in a DMZ, application servers in a middleware segment, and databases in a protected backend segment. Benefits include containing breaches, reducing attack surface, meeting compliance requirements (PCI DSS requires segmentation of cardholder data environments), and improving monitoring by making anomalous cross-segment traffic more visible.", category: "Network Security", difficulty: "Mid", followUps: ["What is micro-segmentation?", "How does zero-trust networking relate to segmentation?"], keywords: ["segmentation", "DMZ", "lateral movement", "zero trust"] },
  { question: "Explain how a DNS amplification DDoS attack works.", answer: "A DNS amplification attack is a reflection-based DDoS attack that exploits open DNS resolvers. The attacker sends DNS queries with a spoofed source IP (the victim's IP) to open DNS resolvers, requesting record types with large responses (typically ANY or TXT records). The DNS servers send their responses to the victim's IP, amplifying the traffic volume. The amplification factor can be 28-54x, meaning a 1 Mbps query stream can generate a 28-54 Mbps attack. Mitigation involves rate-limiting DNS responses, disabling recursion on authoritative servers, implementing BCP38/BCP84 (ingress filtering to prevent IP spoofing), using response rate limiting (RRL), and deploying DDoS mitigation services.", category: "Network Security", difficulty: "Mid", followUps: ["What other protocols can be used for amplification attacks?", "What is BCP38 and why isn't it universally deployed?"], keywords: ["DDoS", "DNS", "amplification", "reflection", "spoofing"] },

  // ============================================================
  // WEB APPLICATION SECURITY
  // ============================================================
  { question: "Explain the difference between stored, reflected, and DOM-based XSS.", answer: "Stored XSS occurs when malicious script is permanently stored on the target server (in a database, forum post, comment) and served to every user who views the affected page. Reflected XSS happens when malicious script is included in a request (usually via URL parameters) and reflected back in the server's response without proper encoding. DOM-based XSS is entirely client-side: the vulnerability exists in JavaScript that reads user-controllable data (like location.hash) and writes it to the DOM using dangerous sinks (innerHTML, document.write, eval). Stored XSS is generally most dangerous because it requires no victim interaction beyond viewing a page. DOM-based XSS can bypass server-side filters since the payload never reaches the server.", category: "Web Application Security", difficulty: "Junior", followUps: ["What is mutation XSS (mXSS)?", "How does Content Security Policy (CSP) mitigate XSS?"], keywords: ["XSS", "stored", "reflected", "DOM", "cross-site scripting"] },
  { question: "How does a CSRF attack work and what defenses exist?", answer: "Cross-Site Request Forgery (CSRF) tricks an authenticated user's browser into making an unintended request to a web application where they're logged in. The attacker creates a malicious page containing a hidden form or image tag that submits a request to the target site. Since the browser automatically includes session cookies, the request appears legitimate. Defenses include: anti-CSRF tokens (synchronizer token pattern - a unique token per session/request that must accompany state-changing requests), SameSite cookie attribute (Strict or Lax prevents cookies from being sent on cross-origin requests), checking Origin/Referer headers, requiring re-authentication for sensitive actions, and using custom request headers (which cannot be set cross-origin by forms).", category: "Web Application Security", difficulty: "Junior", followUps: ["Can CSRF affect API-only backends?", "How does SameSite=Lax differ from SameSite=Strict?"], keywords: ["CSRF", "cross-site", "request forgery", "token", "SameSite"] },
  { question: "What is Server-Side Request Forgery (SSRF) and how can it be exploited?", answer: "SSRF occurs when an attacker can make the server-side application send HTTP requests to an arbitrary destination. The attacker provides a URL that the server fetches, allowing access to internal services, cloud metadata endpoints, or other resources not directly accessible from the internet. Exploitation includes: reading cloud instance metadata (AWS IMDSv1 at 169.254.169.254 to steal IAM credentials), scanning internal networks, accessing internal services (databases, admin panels), reading local files via file:// protocol, and exploiting vulnerable internal services. Notable examples include the 2019 Capital One breach where SSRF on a WAF led to S3 bucket access via IAM role credentials from the metadata service. Mitigations include URL allowlisting, blocking internal IP ranges, using IMDSv2 (requires PUT with hop limit), and network segmentation.", category: "Web Application Security", difficulty: "Mid", followUps: ["What is blind SSRF?", "How does IMDSv2 mitigate SSRF on AWS?"], keywords: ["SSRF", "server-side", "request forgery", "metadata", "internal"] },
  { question: "Explain the concept of Content Security Policy (CSP) and how to implement it effectively.", answer: "CSP is a security header that allows web applications to define trusted sources for content (scripts, styles, images, fonts, etc.), mitigating XSS and data injection attacks. It works by instructing the browser to only execute or render resources from specified origins. Key directives include: script-src (JavaScript sources), style-src (CSS sources), img-src (image sources), connect-src (AJAX/WebSocket destinations), default-src (fallback for unspecified directives), and frame-ancestors (clickjacking protection, replacing X-Frame-Options). Effective implementation uses nonce-based or hash-based policies over domain allowlists: script-src 'nonce-random123' prevents inline script execution unless the nonce matches. Avoid unsafe-inline and unsafe-eval. Start with report-only mode (Content-Security-Policy-Report-Only) to identify violations before enforcement. Use report-uri or report-to to collect violation reports.", category: "Web Application Security", difficulty: "Senior", followUps: ["What is a CSP bypass and how do attackers find them?", "What is Trusted Types?"], keywords: ["CSP", "content security policy", "XSS", "nonce", "header"] },
  { question: "How does SQL injection work in different database backends?", answer: "SQL injection exploits applications that construct SQL queries using unsanitized user input. Techniques vary by DBMS: MySQL uses # or -- for comments, CONCAT() for string concatenation, SLEEP() for time-based blind, and information_schema for metadata enumeration. PostgreSQL uses || for concatenation, pg_sleep() for time-based, and allows stacked queries and COPY TO for file write. MSSQL supports xp_cmdshell for OS command execution, WAITFOR DELAY for time-based, and allows stacked queries by default. Oracle uses || for concatenation, DBMS_PIPE.RECEIVE_MESSAGE for delays, and dual table for testing. SQLite uses sqlite_master for schema enumeration. Beyond UNION-based and blind techniques, advanced methods include out-of-band data exfiltration (DNS lookups, HTTP requests from the database) and second-order injection where input is stored safely but used unsafely later.", category: "Web Application Security", difficulty: "Senior", followUps: ["What is second-order SQL injection?", "How do prepared statements prevent SQL injection?"], keywords: ["SQL injection", "MySQL", "PostgreSQL", "MSSQL", "blind"] },
  { question: "What are the OWASP Top 10 and why do they matter?", answer: "The OWASP Top 10 is a regularly updated consensus document identifying the most critical web application security risks. The 2021 edition includes: A01-Broken Access Control (moved from #5), A02-Cryptographic Failures (renamed from Sensitive Data Exposure), A03-Injection (including XSS, now merged), A04-Insecure Design (new), A05-Security Misconfiguration, A06-Vulnerable and Outdated Components, A07-Identification and Authentication Failures, A08-Software and Data Integrity Failures (new, includes insecure deserialization), A09-Security Logging and Monitoring Failures, A10-Server-Side Request Forgery (new). They matter because they represent consensus from security experts on the most impactful risks, are referenced by compliance standards (PCI DSS, SOC 2), guide security testing priorities, and serve as a baseline for security awareness training.", category: "Web Application Security", difficulty: "Junior", followUps: ["What changed between the 2017 and 2021 versions?", "How do you test for Broken Access Control?"], keywords: ["OWASP", "Top 10", "web security", "risk"] },
  { question: "How do you prevent deserialization vulnerabilities?", answer: "Deserialization vulnerabilities occur when untrusted data is deserialized into objects, potentially allowing remote code execution. In Java, this exploits gadget chains in libraries like Commons Collections through tools like ysoserial. In PHP, unserialize() with __wakeup/__destruct magic methods can trigger code execution. In Python, pickle.loads() can execute arbitrary code. In .NET, BinaryFormatter and ViewState are common targets. Prevention includes: never deserializing untrusted data, using safe serialization formats (JSON with schema validation instead of native serialization), implementing integrity checks (HMAC/signatures) on serialized data, restricting deserialization to expected classes (allowlisting), keeping libraries updated to patch known gadget chains, and using language-specific safe alternatives (Java: JSON-B, Python: json module, .NET: System.Text.Json).", category: "Web Application Security", difficulty: "Senior", followUps: ["What is a gadget chain?", "How does Java's ObjectInputFilter help?"], keywords: ["deserialization", "RCE", "ysoserial", "gadget chain"] },
  { question: "What is HTTP Request Smuggling and how does it work?", answer: "HTTP Request Smuggling exploits differences in how front-end and back-end servers parse HTTP requests, particularly disagreements about where one request ends and the next begins. The attack leverages ambiguous Content-Length and Transfer-Encoding headers. In a CL.TE attack, the front-end uses Content-Length while the back-end uses Transfer-Encoding: chunked, allowing the attacker to smuggle a second request within the first. In a TE.CL attack, the roles are reversed. This can lead to bypassing security controls, accessing internal endpoints, cache poisoning, credential hijacking, and request routing manipulation. Detection involves sending ambiguous requests and observing timing differences or response anomalies. Prevention requires consistent HTTP parsing configuration between all proxy layers and disabling HTTP/1.1 keep-alive or upgrading to HTTP/2 end-to-end.", category: "Web Application Security", difficulty: "Principal", followUps: ["What is HTTP/2 downgrade smuggling?", "How does request smuggling enable cache poisoning?"], keywords: ["HTTP", "smuggling", "CL.TE", "TE.CL", "desync"] },
  { question: "Explain how JWT attacks work and how to prevent them.", answer: "JWT (JSON Web Token) attacks exploit weaknesses in JWT implementation. The 'none' algorithm attack changes the alg header to 'none' and removes the signature, which works if the server doesn't validate the algorithm. Algorithm confusion attacks switch RS256 (asymmetric) to HS256 (symmetric), using the public RSA key as the HMAC secret. JWK/JKU injection embeds or references an attacker-controlled key in the JWT header. Other attacks include KID manipulation for path traversal or SQL injection, expired token acceptance, and weak signing keys vulnerable to brute force. Prevention: always validate the algorithm against an allowlist (never accept 'none'), use separate code paths for symmetric and asymmetric verification, don't trust JWT header claims for key lookup, set and enforce expiration, use strong signing keys (256+ bits for HMAC, 2048+ bits for RSA), and validate all standard claims (iss, aud, exp, nbf).", category: "Web Application Security", difficulty: "Senior", followUps: ["What is the difference between JWS and JWE?", "How does PASETO compare to JWT?"], keywords: ["JWT", "token", "none algorithm", "key confusion", "authentication"] },

  // ============================================================
  // CRYPTOGRAPHY
  // ============================================================
  { question: "What is the difference between symmetric and asymmetric encryption?", answer: "Symmetric encryption uses the same key for both encryption and decryption (AES, ChaCha20, 3DES). It's fast and efficient for bulk data encryption but has a key distribution problem: both parties need the same secret key. Asymmetric encryption uses a key pair (public and private) where data encrypted with one key can only be decrypted with the other (RSA, ECC, Ed25519). It solves key distribution (anyone can encrypt with the public key, only the private key holder can decrypt) but is much slower. In practice, hybrid encryption combines both: asymmetric encryption exchanges a symmetric session key, which then encrypts the actual data. TLS uses this approach: the handshake uses asymmetric key exchange (ECDHE), then symmetric encryption (AES-GCM or ChaCha20-Poly1305) protects the session.", category: "Cryptography", difficulty: "Junior", followUps: ["What is ECDHE and why is it preferred over RSA key exchange?", "What key sizes are equivalent between RSA and ECC?"], keywords: ["symmetric", "asymmetric", "AES", "RSA", "ECC", "hybrid"] },
  { question: "What is a hash function and what properties make it cryptographically secure?", answer: "A cryptographic hash function maps arbitrary-length input to a fixed-length output (digest) with specific security properties. Pre-image resistance means given a hash h, it's computationally infeasible to find any input m where H(m) = h. Second pre-image resistance means given input m1, it's infeasible to find a different m2 where H(m1) = H(m2). Collision resistance means it's infeasible to find any two different inputs m1, m2 where H(m1) = H(m2). Additionally, it should behave as a random oracle (small input changes cause unpredictable output changes, the avalanche effect). MD5 and SHA-1 are broken (practical collision attacks exist). SHA-256 and SHA-3 are currently secure. For password hashing, purpose-built functions like bcrypt, scrypt, or Argon2id are preferred because they add computational cost and memory hardness to resist brute-force attacks.", category: "Cryptography", difficulty: "Junior", followUps: ["Why is MD5 still used in some contexts despite being broken?", "What is a birthday attack?"], keywords: ["hash", "SHA-256", "collision", "pre-image", "bcrypt"] },
  { question: "Explain the concept of perfect forward secrecy and why it matters.", answer: "Perfect Forward Secrecy (PFS) ensures that compromise of long-term cryptographic keys does not compromise past session keys. With PFS, each session generates a unique ephemeral key pair for key exchange (using ECDHE or DHE), and these keys are discarded after the session ends. Without PFS (e.g., RSA key exchange), if the server's private key is later compromised, an attacker who recorded past encrypted traffic can decrypt all of it. With PFS, even with the private key, each session's encryption key was independently generated and destroyed, so past sessions remain protected. This is critical because: nation-state actors may record encrypted traffic for future decryption, key compromises may not be immediately detected, and compliance frameworks increasingly require PFS. TLS 1.3 mandates PFS by removing non-PFS key exchange methods.", category: "Cryptography", difficulty: "Mid", followUps: ["What is the difference between DHE and ECDHE?", "How does TLS 1.3 enforce forward secrecy?"], keywords: ["forward secrecy", "PFS", "ECDHE", "ephemeral", "key exchange"] },
  { question: "What is the difference between encryption and hashing, and when should you use each?", answer: "Encryption is a two-way process: data can be encrypted and then decrypted back to its original form using a key. Hashing is a one-way process: input is transformed into a fixed-length digest that cannot be reversed to obtain the original input. Use encryption when you need to recover the original data (storing credit card numbers, transmitting sensitive messages, protecting data at rest). Use hashing when you only need to verify data matches without knowing the original value (password storage, file integrity verification, digital signatures, data deduplication). For passwords specifically, use slow hash functions with salt (bcrypt, Argon2id) rather than fast hashes (SHA-256). A common mistake is using encryption for passwords (it's reversible, so a key compromise exposes all passwords) or using hashing for data you need to decrypt later.", category: "Cryptography", difficulty: "Junior", followUps: ["What is a salt and why is it important for password hashing?", "What is a pepper in password hashing?"], keywords: ["encryption", "hashing", "password", "bcrypt", "salt"] },
  { question: "How does a man-in-the-middle attack work against TLS, and what prevents it?", answer: "A MITM attack against TLS attempts to intercept the encrypted connection by positioning between client and server. Without proper verification, the attacker could present their own certificate to the client while connecting to the real server, decrypting and re-encrypting traffic in transit. TLS prevents this through certificate verification: the server presents an X.509 certificate signed by a trusted Certificate Authority (CA), and the client verifies the chain of trust back to a root CA in its trust store, checks the certificate isn't expired or revoked (via CRL or OCSP), and verifies the domain name matches the certificate's Common Name or Subject Alternative Names. Additional protections include Certificate Transparency (public logs of all issued certificates), HSTS (prevents SSL stripping), and certificate pinning (associates a host with its expected certificate or public key). Certificate Transparency has been particularly effective at detecting mis-issued certificates.", category: "Cryptography", difficulty: "Mid", followUps: ["What is certificate pinning and what are its drawbacks?", "How does Certificate Transparency work?"], keywords: ["MITM", "TLS", "certificate", "CA", "trust"] },

  // ============================================================
  // OPERATING SYSTEMS
  // ============================================================
  { question: "What are the key differences between Linux and Windows security models?", answer: "Linux uses a DAC (Discretionary Access Control) model by default with user/group/other permissions (rwx), enhanced by optional MAC (Mandatory Access Control) systems like SELinux or AppArmor. Windows uses a more granular ACL-based model with SIDs (Security Identifiers), ACEs (Access Control Entries), and supports both DACL and SACL for access control and auditing. Key differences: Linux runs as root vs Windows runs as SYSTEM/Administrator; Linux uses sudo for privilege elevation vs Windows uses UAC; Linux file permissions are simpler (chmod/chown) vs Windows NTFS ACLs are more granular; Linux uses iptables/nftables vs Windows Firewall; Linux kernel exploits often target SUID binaries vs Windows targets services and drivers; Linux logs to syslog/journald vs Windows Event Log. Both support privilege separation but implement it differently.", category: "Operating Systems", difficulty: "Junior", followUps: ["What is SELinux and how does it enhance security?", "How does Windows UAC work?"], keywords: ["Linux", "Windows", "permissions", "ACL", "DAC", "MAC"] },
  { question: "Explain how Linux file permissions work, including SUID, SGID, and sticky bit.", answer: "Linux file permissions use a 9-bit model: read (4), write (2), execute (1) for owner, group, and others. Beyond this, three special bits exist: SUID (Set User ID, 4000) on an executable causes it to run with the file owner's permissions rather than the executing user's - this is how passwd can write to /etc/shadow despite being run by unprivileged users, but it's a major attack vector if SUID binaries have vulnerabilities. SGID (Set Group ID, 2000) on executables runs with the file's group permissions; on directories, new files inherit the directory's group. Sticky bit (1000) on directories prevents users from deleting files they don't own, even if they have write permission on the directory (used on /tmp). Privilege escalation commonly targets SUID binaries: find / -perm -4000 lists all SUID files, and GTFOBins documents exploitation techniques for common SUID binaries.", category: "Operating Systems", difficulty: "Mid", followUps: ["What is a capability in Linux and how does it relate to SUID?", "How do you find all SUID binaries on a system?"], keywords: ["permissions", "SUID", "SGID", "sticky bit", "privilege escalation"] },
  { question: "How does Windows Active Directory authentication work (Kerberos)?", answer: "Kerberos authentication in AD uses a ticket-based system. The process: (1) AS-REQ: client sends username to the KDC (Domain Controller), which returns a TGT (Ticket Granting Ticket) encrypted with the user's password hash (AS-REP). (2) TGS-REQ: client presents TGT to request a service ticket for a specific resource, receiving a TGS (Ticket Granting Service ticket). (3) AP-REQ: client presents the service ticket to the target service. The TGT is encrypted with the krbtgt account's hash, and service tickets are encrypted with the target service's password hash. This architecture enables several attacks: Kerberoasting (requesting service tickets for SPNs and cracking them offline), AS-REP Roasting (targeting accounts without pre-authentication), Golden Ticket (forging TGTs with compromised krbtgt hash), Silver Ticket (forging service tickets), and Pass-the-Ticket (reusing stolen tickets).", category: "Operating Systems", difficulty: "Senior", followUps: ["What is the difference between a Golden Ticket and a Silver Ticket?", "How does Kerberos delegation work and what are its security implications?"], keywords: ["Kerberos", "Active Directory", "TGT", "KDC", "authentication"] },
  { question: "What are Windows Event IDs and which are most important for security monitoring?", answer: "Windows Event IDs are numeric identifiers for events logged in the Windows Event Log system. Critical security Event IDs include: 4624/4625 (successful/failed logon with logon types: 2=interactive, 3=network, 7=unlock, 10=RDP), 4648 (explicit credential logon), 4672 (special privilege logon), 4688 (process creation - enable command line logging), 4697 (service installation), 4698-4702 (scheduled task events), 4720 (account creation), 4732 (user added to privileged group), 4768/4769 (Kerberos TGT/TGS requests for Kerberoasting detection), 4776 (NTLM authentication), 1102 (audit log cleared - evidence tampering indicator), 7045 (new service installed via SCM). Sysmon extends this with EventID 1 (process create with hashes), 3 (network connection), 7 (image loaded), 10 (process access for credential dumping), 11 (file create). Monitoring these IDs with correlation rules in a SIEM enables detection of most common attack techniques.", category: "Operating Systems", difficulty: "Senior", followUps: ["What is Sysmon and why should you deploy it?", "How do you detect Kerberoasting using Event IDs?"], keywords: ["Event ID", "Windows", "logging", "4624", "4688", "Sysmon"] },

  // ============================================================
  // INCIDENT RESPONSE
  // ============================================================
  { question: "What are the six phases of incident response according to NIST?", answer: "NIST SP 800-61 defines six phases: (1) Preparation: establishing IR policy, team, tools, communication channels, and conducting exercises. (2) Detection and Analysis: monitoring for indicators of compromise, validating alerts, determining scope and impact, classifying severity. (3) Containment: short-term (isolate affected systems) and long-term (apply temporary fixes to prevent spread while maintaining evidence). (4) Eradication: removing the threat (malware, unauthorized access, vulnerabilities exploited). (5) Recovery: restoring systems to normal operation, monitoring for re-infection, validating system integrity. (6) Post-Incident Activity: lessons learned meeting within 1-2 weeks, updating IR plans, improving detection capabilities based on gaps identified. The phases are not strictly linear - you may cycle between detection, containment, and eradication as new information emerges.", category: "Incident Response", difficulty: "Junior", followUps: ["What should an IR plan include?", "How do you prioritize incidents when multiple occur simultaneously?"], keywords: ["incident response", "NIST", "containment", "eradication", "recovery"] },
  { question: "You discover an active ransomware infection. Walk through your response.", answer: "Immediate actions (first 15 minutes): disconnect affected systems from the network (don't power off - preserve memory), notify the IR team lead, begin documenting timeline and actions taken, identify the ransomware variant if possible from ransom note or file extensions, check if encryption is still actively spreading. Containment (first hour): isolate the affected network segment, disable shared drives and network shares, block C2 domains and IPs at the firewall, preserve at least one encrypted system for forensic analysis (image the disk, capture memory dump), check backup integrity (before connecting backup systems). Investigation: determine initial access vector (phishing email, exposed RDP, supply chain), identify patient zero and lateral movement path, assess data exfiltration (double extortion), determine scope of encrypted systems. Recovery: restore from clean backups (verify no backdoors), rebuild compromised systems from known-good images, reset all credentials (the attacker likely has domain admin). Do not pay the ransom unless as absolute last resort with legal/executive approval.", category: "Incident Response", difficulty: "Senior", followUps: ["Should you ever pay the ransom?", "How do you determine if data was exfiltrated before encryption?"], keywords: ["ransomware", "incident", "containment", "recovery", "backup"] },
  { question: "What is the chain of custody and why is it important in digital forensics?", answer: "Chain of custody is the documented, chronological record of who has handled, accessed, or transferred a piece of evidence from collection through presentation in court. It establishes that evidence has not been tampered with and is admissible in legal proceedings. Key elements include: who collected the evidence (name, role), when it was collected (date, time, timezone), where it was collected (system, location), how it was collected (tools, methods), hash values of original evidence (MD5+SHA256 for integrity verification), every transfer of custody (who gave it to whom, when, why), and storage conditions (locked evidence room, access logs). Failure to maintain chain of custody can result in evidence being ruled inadmissible, criminal cases being dismissed, or inability to pursue legal action against attackers. Digital evidence should be imaged (bit-for-bit copy) with write blockers, and analysis performed on copies, never the original.", category: "Incident Response", difficulty: "Mid", followUps: ["What tools do you use for forensic imaging?", "How do you handle volatile evidence?"], keywords: ["chain of custody", "forensics", "evidence", "integrity", "admissible"] },

  // ============================================================
  // CLOUD SECURITY
  // ============================================================
  { question: "What are the biggest security risks specific to cloud environments?", answer: "Cloud-specific risks include: misconfigured storage buckets (S3, Azure Blob, GCS) exposing sensitive data publicly, overly permissive IAM policies (especially wildcard permissions like Action: * Resource: *), instance metadata service abuse (SSRF to 169.254.169.254 for credential theft), insecure serverless function configurations (Lambda with excessive permissions), container escape vulnerabilities, shared responsibility model misunderstandings (customers assuming the cloud provider handles security they don't), exposed management consoles, insufficient logging and monitoring (CloudTrail not enabled or logs not retained), cross-account trust misconfigurations, and secrets hardcoded in code or environment variables instead of secrets managers. The ephemeral nature of cloud resources makes traditional asset inventory and vulnerability management harder, and the speed of cloud provisioning can outpace security review.", category: "Cloud Security", difficulty: "Mid", followUps: ["What is the shared responsibility model?", "How do you secure an S3 bucket?"], keywords: ["cloud", "AWS", "Azure", "GCP", "IAM", "misconfiguration"] },
  { question: "How does the AWS shared responsibility model work?", answer: "AWS shared responsibility divides security obligations: AWS is responsible for security 'of' the cloud (physical infrastructure, hardware, hypervisor, managed service internals, global network), while the customer is responsible for security 'in' the cloud (data, IAM, OS/network/firewall configuration, client-side encryption, server-side encryption configuration, and network traffic protection). The specific division varies by service type: for IaaS (EC2), customers manage OS patches, firewall rules, and everything above the hypervisor. For PaaS (RDS), AWS manages OS patching and the database engine, but customers handle access control and data encryption. For SaaS (S3), AWS manages almost everything, but customers control bucket policies, access permissions, and data classification. A common security failure is assuming AWS handles something that's actually the customer's responsibility, especially around patching, access management, and encryption key management.", category: "Cloud Security", difficulty: "Junior", followUps: ["How does this model differ for Azure and GCP?", "What is AWS's responsibility for managed services like RDS?"], keywords: ["shared responsibility", "AWS", "IaaS", "PaaS", "SaaS"] },
  { question: "What is an IAM privilege escalation in AWS and how do you prevent it?", answer: "IAM privilege escalation occurs when a user or role with limited permissions exploits their existing permissions to gain higher-level access. Common vectors include: iam:CreatePolicyVersion (create a new policy version granting admin), iam:SetDefaultPolicyVersion (set an older, more permissive policy as default), iam:PassRole + lambda/ec2:RunInstances (pass a high-privilege role to a Lambda or EC2 instance you control), iam:CreateLoginProfile (create console access for another user), iam:AttachUserPolicy/AttachRolePolicy (attach AdministratorAccess to yourself), iam:PutUserPolicy (add inline admin policy), and sts:AssumeRole (assume a more privileged role). Prevention includes: least privilege IAM policies, AWS Organizations SCPs as guardrails, IAM Access Analyzer to identify overly permissive policies, regular IAM credential reports and access auditing, restricting who can modify IAM, implementing permissions boundaries, and using tools like Pacu or PMapper to audit escalation paths.", category: "Cloud Security", difficulty: "Senior", followUps: ["What are IAM permissions boundaries?", "How does AWS Organizations SCP prevent privilege escalation?"], keywords: ["IAM", "privilege escalation", "AWS", "policy", "least privilege"] },

  // ============================================================
  // PENETRATION TESTING
  // ============================================================
  { question: "What is the difference between a vulnerability assessment and a penetration test?", answer: "A vulnerability assessment systematically identifies and classifies vulnerabilities in systems using automated scanners (Nessus, Qualys, OpenVAS) and manual verification, producing a prioritized list of findings with remediation guidance. It's broad but shallow - it identifies weaknesses without exploiting them. A penetration test goes further by actively exploiting vulnerabilities to demonstrate real-world impact, chain multiple weaknesses, and assess the effectiveness of security controls. It's deeper but narrower in scope. A pentest simulates an actual attacker, showing how far they could get and what data they could access. Vulnerability assessments are typically automated and repeatable, while pentests require skilled human testers making creative decisions. Organizations usually need both: regular vulnerability assessments for continuous visibility and periodic penetration tests for realistic risk validation.", category: "Penetration Testing", difficulty: "Junior", followUps: ["What is a red team engagement vs a penetration test?", "How often should penetration tests be performed?"], keywords: ["vulnerability assessment", "penetration test", "scanning", "exploitation"] },
  { question: "Explain the difference between black box, white box, and gray box testing.", answer: "Black box testing simulates an external attacker with no prior knowledge of the target - the tester starts with only publicly available information and must discover the attack surface, technology stack, and vulnerabilities independently. White box testing provides the tester with full access to source code, architecture documentation, credentials, and internal network diagrams, enabling thorough analysis including code review and comprehensive coverage of all attack surfaces. Gray box testing falls between: the tester receives some information (like valid credentials, network diagrams, or API documentation) but not full source code access, simulating an insider threat or a compromised account scenario. Black box is most realistic for external threat simulation but may miss complex vulnerabilities due to time constraints. White box provides the most thorough coverage but is least realistic. Gray box balances coverage with realism and is often the most cost-effective approach for organizations.", category: "Penetration Testing", difficulty: "Junior", followUps: ["When would you recommend each type?", "What is crystal box testing?"], keywords: ["black box", "white box", "gray box", "testing methodology"] },
  { question: "You find a SQL injection vulnerability during a pentest. Walk through exploitation.", answer: "Systematic exploitation: (1) Confirm the vulnerability: test single quote, boolean conditions (AND 1=1 vs AND 1=2), time-based (AND SLEEP(5)). (2) Determine the DBMS: based on error messages, syntax differences, or banner grabbing (@@version for MySQL/MSSQL, version() for PostgreSQL). (3) Find column count: ORDER BY N (incrementing until error). (4) Identify output positions: UNION SELECT 1,2,3,...,N and see which numbers appear in the response. (5) Extract metadata: database(), user(), @@version in output positions. (6) Enumerate databases: SELECT schema_name FROM information_schema.schemata. (7) Enumerate tables: SELECT table_name FROM information_schema.tables WHERE table_schema='target_db'. (8) Enumerate columns: SELECT column_name FROM information_schema.columns WHERE table_name='users'. (9) Extract data: SELECT username,password FROM users. (10) Attempt privilege escalation: INTO OUTFILE for webshell (MySQL), xp_cmdshell (MSSQL), COPY TO for file write (PostgreSQL). Document each step with screenshots and note the data accessible through the vulnerability for the report.", category: "Penetration Testing", difficulty: "Mid", followUps: ["How would you exploit blind SQL injection?", "What if the application has a WAF?"], keywords: ["SQL injection", "exploitation", "UNION", "information_schema", "pentest"] },
  { question: "How do you approach an internal Active Directory penetration test?", answer: "Phase 1 - Reconnaissance: identify domain controllers (nslookup -type=SRV _ldap._tcp.dc._msdcs.domain.com), run BloodHound/SharpHound for AD relationship mapping, enumerate users/groups/SPNs (Get-ADUser, PowerView). Phase 2 - Initial Access: LLMNR/NBT-NS poisoning with Responder to capture NTLMv2 hashes, AS-REP Roasting for accounts without Kerberos pre-auth, password spraying (careful of lockout), check for default credentials on services. Phase 3 - Privilege Escalation: Kerberoast service accounts (GetUserSPNs.py), crack captured hashes, check for privilege escalation paths in BloodHound (shortest path to Domain Admin), exploit vulnerable Group Policy, check for unconstrained delegation. Phase 4 - Lateral Movement: pass-the-hash/ticket, CrackMapExec for credential validation across hosts, WMI/PSRemoting/SMB execution. Phase 5 - Domain Dominance: DCSync for full credential dump, Golden Ticket creation for persistence. Throughout: document everything, avoid disrupting production, follow rules of engagement, and verify findings before reporting.", category: "Penetration Testing", difficulty: "Senior", followUps: ["How do you avoid detection during an AD pentest?", "What would you do if you can't crack any hashes?"], keywords: ["Active Directory", "pentest", "Kerberoasting", "BloodHound", "lateral movement"] },

  // ============================================================
  // MALWARE ANALYSIS
  // ============================================================
  { question: "What is the difference between static and dynamic malware analysis?", answer: "Static analysis examines malware without executing it: reviewing file properties (PE headers, sections, imports, exports), extracting strings (URLs, IPs, registry keys, file paths), checking file hashes against threat intelligence, analyzing with disassemblers (IDA Pro, Ghidra) to understand code logic, and identifying packing/obfuscation. Dynamic analysis runs the malware in a controlled environment (sandbox) and monitors its behavior: process creation, file system changes, registry modifications, network connections, DNS queries, API calls, and dropped files. Static analysis is safer (no execution) and provides understanding of full capability, but can be defeated by obfuscation, encryption, and anti-analysis techniques. Dynamic analysis shows actual behavior but only reveals the code path triggered during the specific execution (environment-dependent behavior may be missed). Best practice combines both: static analysis first to understand the sample, then dynamic analysis to validate findings and observe runtime behavior.", category: "Malware Analysis", difficulty: "Junior", followUps: ["What tools do you use for static analysis?", "What is a malware sandbox?"], keywords: ["static analysis", "dynamic analysis", "malware", "reverse engineering", "sandbox"] },
  { question: "How do you identify and unpack a packed malware sample?", answer: "Identification: check for high entropy (>7.0) in sections using tools like Detect It Easy or PEiD, look for few imports (packed binaries typically only import LoadLibrary and GetProcAddress for dynamic resolution), check section names for packer signatures (UPX0/UPX1, .aspack, .themida), compare virtual size vs raw size of sections (large discrepancy indicates runtime unpacking), and run the sample through Exeinfo PE or TrID. Unpacking approaches: for known packers (UPX), use the built-in unpacker (upx -d sample.exe). For custom or commercial packers, use dynamic unpacking: run in a debugger (x64dbg), set breakpoints on VirtualAlloc/VirtualProtect to find the unpacking buffer, look for a jump to the OEP (Original Entry Point) after unpacking, and dump the process memory at that point using Scylla or pe-sieve. For heavily protected samples (Themida, VMProtect), you may need to trace through virtualized code or use specialized tools. After dumping, rebuild the import table using Scylla's IAT Autosearch.", category: "Malware Analysis", difficulty: "Senior", followUps: ["What is a UPX stub?", "How do you handle samples with anti-debugging?"], keywords: ["packing", "UPX", "entropy", "unpacking", "OEP", "debugger"] },

  // ============================================================
  // SECURITY ARCHITECTURE
  // ============================================================
  { question: "What is zero-trust architecture and how do you implement it?", answer: "Zero Trust is a security model that eliminates implicit trust and requires continuous verification for every user, device, and network flow, regardless of whether they're inside or outside the traditional network perimeter. Core principles: never trust, always verify; assume breach; apply least-privilege access. Implementation involves: strong identity verification for all users (MFA, conditional access), device health validation (endpoint compliance checks before granting access), micro-segmentation of networks, encryption of all traffic (even internal), continuous monitoring and adaptive access policies, and just-in-time/just-enough access provisioning. Key technologies include identity-aware proxies (Google BeyondCorp, Azure AD Application Proxy), software-defined perimeters (SDP/ZTNA), micro-segmentation platforms, and continuous authentication. The transition from perimeter-based security is typically gradual: start with identity (MFA everywhere), then device trust, then network segmentation, while maintaining visibility through logging and analytics.", category: "Security Architecture", difficulty: "Senior", followUps: ["How does Google BeyondCorp implement zero trust?", "What are the challenges of implementing zero trust in legacy environments?"], keywords: ["zero trust", "architecture", "MFA", "micro-segmentation", "BeyondCorp"] },
  { question: "Explain defense in depth and give practical examples.", answer: "Defense in depth is a security strategy that layers multiple independent security controls so that if one fails, others continue to provide protection. This is based on the military concept of not relying on a single defensive line. Practical layers include: (1) Physical: locks, cameras, biometric access to data centers. (2) Network: firewalls, IDS/IPS, network segmentation, VPN, DDoS protection. (3) Host: endpoint protection (EDR), host-based firewall, patch management, hardened OS configuration. (4) Application: input validation, authentication, authorization, code review, WAF, SAST/DAST. (5) Data: encryption at rest and in transit, DLP, access controls, backups, data classification. (6) People: security awareness training, phishing simulations, background checks, separation of duties. (7) Operational: logging and monitoring, incident response, vulnerability management, penetration testing. Each layer addresses different attack vectors, and the combination makes it exponentially harder for an attacker to reach their objective.", category: "Security Architecture", difficulty: "Junior", followUps: ["What's the difference between defense in depth and layered security?", "How do you decide how many layers are enough?"], keywords: ["defense in depth", "layered security", "controls", "risk", "architecture"] },

  // ============================================================
  // COMPLIANCE AND GRC
  // ============================================================
  { question: "What is PCI DSS and what are its key requirements?", answer: "PCI DSS (Payment Card Industry Data Security Standard) is a security standard for organizations that handle credit card data. Version 4.0 (current) has 12 requirements grouped into 6 goals: (1) Build and Maintain a Secure Network: install and maintain network security controls, apply secure configurations to all system components. (2) Protect Account Data: protect stored account data (encryption, masking, hashing), protect cardholder data with strong cryptography during transmission over open networks. (3) Maintain a Vulnerability Management Program: protect all systems against malware, develop and maintain secure systems and software. (4) Implement Strong Access Control Measures: restrict access on need-to-know basis, identify users and authenticate access, restrict physical access. (5) Regularly Monitor and Test Networks: log and monitor all access, regularly test security systems and processes. (6) Maintain an Information Security Policy: support information security with organizational policies and programs. Compliance requires annual assessment (SAQ for smaller merchants, QSA audit for level 1 merchants processing >6M transactions), quarterly network scans by an ASV, and ongoing control maintenance.", category: "Compliance/GRC", difficulty: "Mid", followUps: ["What is the difference between PCI DSS levels 1-4?", "How does network segmentation reduce PCI scope?"], keywords: ["PCI DSS", "compliance", "payment card", "encryption", "assessment"] },
  { question: "What is the NIST Cybersecurity Framework and how do organizations use it?", answer: "The NIST CSF is a voluntary framework providing guidance for managing cybersecurity risk, widely adopted by both government and private sector organizations. It consists of five core functions: Identify (asset management, risk assessment, governance), Protect (access control, awareness training, data security, maintenance), Detect (anomalies and events, security continuous monitoring, detection processes), Respond (response planning, communications, analysis, mitigation, improvements), Recover (recovery planning, improvements, communications). Each function contains categories and subcategories mapped to informative references (NIST 800-53, ISO 27001, CIS Controls, COBIT). Organizations use it to: assess current cybersecurity posture (Current Profile), define target state (Target Profile), identify gaps, prioritize improvements, and communicate risk to leadership. The framework uses Implementation Tiers (Partial, Risk Informed, Repeatable, Adaptive) to characterize an organization's cybersecurity risk management maturity. NIST CSF 2.0 added a sixth function: Govern, emphasizing organizational context and supply chain risk.", category: "Compliance/GRC", difficulty: "Mid", followUps: ["How does NIST CSF differ from ISO 27001?", "What are the NIST CSF implementation tiers?"], keywords: ["NIST", "CSF", "framework", "identify", "protect", "detect", "respond", "recover"] },

  // ============================================================
  // DEVSECOPS
  // ============================================================
  { question: "How do you integrate security into a CI/CD pipeline?", answer: "Security integration at each pipeline stage: (1) Pre-commit: secret scanning (truffleHog, git-secrets, Gitleaks) to prevent credential commits, IDE security plugins for real-time feedback. (2) Build: SAST (Static Application Security Testing) with tools like Semgrep, SonarQube, CodeQL scanning source code for vulnerabilities, SCA (Software Composition Analysis) with Dependabot, Snyk, or OWASP Dependency-Check for vulnerable dependencies, container image scanning (Trivy, Grype) for base image vulnerabilities. (3) Test: DAST (Dynamic Application Security Testing) with OWASP ZAP or Nuclei scanning the running application, IAST (Interactive Application Security Testing) combining static and dynamic analysis, fuzzing for edge cases. (4) Deploy: IaC scanning (Checkov, tfsec) for infrastructure misconfigurations, policy enforcement (OPA/Rego) for deployment gates, signing and verification of artifacts. (5) Runtime: RASP (Runtime Application Self-Protection), cloud security posture management (CSPM), and continuous monitoring. The key is automation: security checks should run automatically on every commit without manual intervention, and findings should break the build only for high-severity issues to avoid alert fatigue.", category: "DevSecOps", difficulty: "Mid", followUps: ["What is 'shift-left' security?", "How do you handle false positives in SAST without losing developer trust?"], keywords: ["DevSecOps", "CI/CD", "SAST", "DAST", "SCA", "pipeline", "shift-left"] },
  { question: "What is Software Composition Analysis (SCA) and why is it critical?", answer: "SCA identifies and tracks open-source and third-party components in software projects, checking them against vulnerability databases (NVD, GitHub Advisory, OSV) and evaluating license compliance. It's critical because modern applications are 80-90% third-party code: a typical Node.js project has hundreds of transitive dependencies, any of which could introduce vulnerabilities. Notable supply chain attacks include: event-stream (cryptocurrency theft via compromised npm package), SolarWinds (nation-state backdoor in a build system), Log4Shell (critical RCE in ubiquitous logging library), and ua-parser-js (cryptominer injected into popular package). SCA tools (Snyk, Dependabot, OWASP Dependency-Check, Mend/WhiteSource) generate Software Bills of Materials (SBOMs), alert on known CVEs, suggest version upgrades with minimal breaking changes, and can auto-create pull requests for patches. SBOM requirements are now mandated by US Executive Order 14028 for government software suppliers.", category: "DevSecOps", difficulty: "Mid", followUps: ["What is an SBOM and why is it important?", "How do you handle a critical vulnerability in a transitive dependency?"], keywords: ["SCA", "dependencies", "SBOM", "supply chain", "Log4Shell", "npm"] },

  // ============================================================
  // THREAT INTELLIGENCE
  // ============================================================
  { question: "What is the MITRE ATT&CK framework and how do you use it?", answer: "MITRE ATT&CK (Adversarial Tactics, Techniques, and Common Knowledge) is a knowledge base of adversary behavior organized by tactics (the why - Initial Access, Execution, Persistence, Privilege Escalation, Defense Evasion, Credential Access, Discovery, Lateral Movement, Collection, Command and Control, Exfiltration, Impact) and techniques (the how - specific methods under each tactic, like T1566 Phishing under Initial Access). Each technique includes sub-techniques, real-world procedure examples, detection guidance, and mitigations. Usage includes: mapping detected threats to techniques for common language across teams, identifying detection gaps by overlaying coverage against the matrix, prioritizing security investments based on the most commonly observed techniques for your sector, developing detection rules tagged with ATT&CK IDs, threat hunting by systematically searching for evidence of specific techniques, and red team planning using the framework to design realistic attack scenarios.", category: "Threat Intelligence", difficulty: "Mid", followUps: ["What is the ATT&CK Navigator?", "How do you measure your ATT&CK coverage?"], keywords: ["MITRE ATT&CK", "tactics", "techniques", "TTP", "threat intelligence"] },
  { question: "What are Indicators of Compromise (IOCs) vs Indicators of Attack (IOAs)?", answer: "IOCs are forensic artifacts that indicate a system has been compromised - they are evidence of past activity: file hashes (MD5/SHA256 of malware), IP addresses (C2 servers), domain names, URLs, registry keys, email addresses, mutexes, and network signatures. IOCs are reactive and specific; they become outdated as attackers change infrastructure. IOAs focus on active adversary behavior and intent rather than static artifacts: techniques like credential dumping (accessing lsass.exe), lateral movement patterns (unusual SMB connections between workstations), privilege escalation attempts, or data staging for exfiltration. IOAs are proactive and technique-based; they remain relevant even when attackers change their tools and infrastructure. David Bianco's Pyramid of Pain illustrates this: hash values are easy for attackers to change (bottom), while TTPs (Tactics, Techniques, Procedures) are hardest to change (top). Effective threat detection combines both: IOCs for known-threat matching and IOAs for behavioral detection.", category: "Threat Intelligence", difficulty: "Mid", followUps: ["What is the Pyramid of Pain?", "How do you operationalize threat intelligence IOCs?"], keywords: ["IOC", "IOA", "indicators", "threat intelligence", "detection"] },
];
